\begin{aligned}
\widetilde\epsilon_{\mu_1\cdots\mu_n}
\mathrm dx^{\mu_1}\wedge\cdots\wedge\mathrm dx^{\mu_n}
={}&\widetilde\epsilon_{\mu_1\cdots\mu_n}
\frac{\partial x^{\mu_1}}{\partial x^{\mu_1'}}\cdots
\frac{\partial x^{\mu_n}}{\partial x^{\mu_n'}}
\mathrm dx^{\mu_1'}\wedge\cdots\wedge\mathrm dx^{\mu_n'}\\
={}&\left|\frac{\partial x^\mu}{\partial x^{\mu'}}\right|
\widetilde\epsilon_{\mu_1'\cdots\mu_n'}
\mathrm dx^{\mu_1'}\wedge\cdots\wedge\mathrm dx^{\mu_n'}.
\end{aligned}
\tag{2.93}
